<?php
use App\Models\Branch;
use App\Models\Warehouse;
use App\Support\Tenancy\CurrentCompany;
use Flux\Flux;
use Illuminate\Pagination\LengthAwarePaginator;
use Illuminate\Support\Facades\Gate;
use Illuminate\Validation\Rule;
use Livewire\Attributes\Computed;
use Livewire\Attributes\Title;
use Livewire\Component;
use Livewire\WithPagination;

new #[Title('Almacenes')] class extends Component {
    use WithPagination;
    public string $search=''; public ?int $editingId=null; public ?int $branchId=null; public string $code=''; public string $name=''; public bool $isActive=true;
    public function updatedSearch():void{$this->resetPage();}
    public function create():void{Gate::authorize('create',Warehouse::class);$this->resetForm();Flux::modal('warehouse-form')->show();}
    public function edit(int $id):void{$item=Warehouse::query()->findOrFail($id);Gate::authorize('update',$item);$this->editingId=$item->id;$this->branchId=$item->branch_id;$this->code=$item->code;$this->name=$item->name;$this->isActive=$item->is_active;Flux::modal('warehouse-form')->show();}
    public function save():void{$companyId=app(CurrentCompany::class)->id();$item=$this->editingId?Warehouse::query()->findOrFail($this->editingId):null;Gate::authorize($item?'update':'create',$item??Warehouse::class);$data=$this->validate(['branchId'=>['required',Rule::exists('branches','id')->where('company_id',$companyId)],'code'=>['required','string','max:50',Rule::unique('warehouses','code')->where(fn($q)=>$q->where('company_id',$companyId)->where('branch_id',$this->branchId))->ignore($item)],'name'=>['required','string','max:255'],'isActive'=>['boolean']]);Warehouse::query()->updateOrCreate(['id'=>$item?->id],['company_id'=>$companyId,'branch_id'=>$data['branchId'],'code'=>$data['code'],'name'=>$data['name'],'is_active'=>$data['isActive']]);Flux::modal('warehouse-form')->close();Flux::toast(variant:'success',text:$item?'Almacén actualizado.':'Almacén creado.');$this->resetForm();}
    public function toggle(int $id):void{$item=Warehouse::query()->findOrFail($id);Gate::authorize('update',$item);$item->update(['is_active'=>!$item->is_active]);Flux::toast(variant:'success',text:'Estado actualizado.');}
    #[Computed]public function warehouses():LengthAwarePaginator{return Warehouse::query()->with('branch:id,name')->withCount('stockBalances')->when($this->search,fn($q)=>$q->where(fn($n)=>$n->where('name','like','%'.$this->search.'%')->orWhere('code','like','%'.$this->search.'%')))->latest()->paginate(12);}
    #[Computed]public function branches(){return Branch::query()->where('is_active',true)->orderBy('name')->get(['id','name']);}
    private function resetForm():void{$this->reset(['editingId','branchId','code','name']);$this->isActive=true;$this->resetValidation();}
}; ?>
