x:table.cell></flux:table.row>@endforelse</flux:table.rows></flux:table></div></flux:card><flux:modal name="warehouse-form" class="max-w-lg"><form wire:submit="save" class="space-y-5"><flux:heading size="lg">{{ $editingId?'Editar almacén':'Nuevo almacén' }}</flux:heading><flux:select wire:model="branchId" label="Sucursal" required><flux:select.option value="">Seleccionar</flux:select.option>@foreach($this->branches as $branch)<flux:select.option :value="$branch->id">{{ $branch->name }}</flux:select.option>@endforeach</flux:select><div class="grid gap-4 sm:grid-cols-2"><flux:input wire:model="code" label="Código" required /><flux:input wire:model="name" label="Nombre" required /></div><flux:switch wire:model="isActive" label="Activo" /><div class="flex justify-end gap-3"><flux:modal.close><flux:button variant="ghost">Cancelar</flux:button></flux:modal.close><flux:button type="submit" variant="primary">Guardar</flux:button></div></form></flux:modal></div>
